from hermes_tools import terminal
script = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)
assert wb.sheetnames == ['Task','Data'], wb.sheetnames
ws=wb['Task']
errors=[]
# Verify target formula counts and sample exact formulas.
for r1, r2 in [(12,17),(19,24),(26,31)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            col=get_column_letter(c)
            expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
            if ws.cell(r,c).value != expected:
                errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, expected))
for out_r, ren_r, grid_r, base_r in zip(range(35,41), range(12,18), range(19,25), range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{ren_r}-{col}{grid_r})/{col}{base_r}*100'
        if ws.cell(out_r,c).value != expected:
            errors.append((ws.cell(out_r,c).coordinate, ws.cell(out_r,c).value, expected))
stats = {42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE'}
for c in range(8,13):
    col=get_column_letter(c)
    expected_map={
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=PERCENTILE({col}35:{col}40,0.25)',
        47:f'=PERCENTILE({col}35:{col}40,0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for r, expected in expected_map.items():
        if ws.cell(r,c).value != expected:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, expected))
print('Target formula cells verified:', 90+30+30+5)
print('Errors:', len(errors))
if errors:
    for e in errors[:10]: print('ERR', e)
    raise SystemExit(1)
print('\nFormula samples after re-open:')
for rng in ['H12:L12','H17:L17','H19:L19','H24:L24','H26:L26','H31:L31','H35:L35','H40:L40','H42:L47','H50:L50']:
    print(rng)
    for row in ws[rng]:
        print([f'{cell.coordinate}={cell.value}' for cell in row])
# Save again to verify save integrity.
wb.save(path)
print('\nSave verification: OK')
'''
res=terminal('python3 - <<\'PY\'\n'+script+'\nPY', timeout=120, workdir='/root')
print(res['output'])
if res.get('exit_code') != 0:
    print('exit_code', res.get('exit_code'))
